pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < address(this).balance);
        // fund c through its public receive()
        (bool okFund, ) = address(c).call{value: amount}("");
        assertTrue(okFund);
        // Owner of c is this test contract (msg.sender at deploy)
        uint256 ownerBefore = address(this).balance;
        uint256 cBefore = address(c).balance;
        // drive c through withdraw as Owner
        c.withdraw();
        // General rule: withdraw pays the whole held balance to the Owner,
        // so the Owner receives exactly what c held.
        assertTrue(address(this).balance == ownerBefore + cBefore && address(c).balance == 0);
    }
}

