pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address owner) public {
        vm.assume(owner != address(0));
        vm.assume(amount > 0);

        // deploy a C owned by the fuzzed actor
        vm.prank(owner);
        C target = new C();

        // fund the contract directly
        vm.deal(owner, amount);
        vm.prank(owner);
        (bool sent, ) = payable(address(target)).call{value: amount}("");
        assertTrue(sent);
        assertTrue(address(target).balance == amount);

        // owner withdraws everything
        vm.prank(owner);
        try target.withdraw() {
            // GENERAL RULE: after a successful owner withdraw, the contract retains no funds
            assertTrue(address(target).balance == 0);
        } catch {
            // a revert is only admissible if the owner rejects ETH; assert nothing else here
            assertTrue(address(target).balance == amount);
        }
    }
}

