pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 ownerSeed) public {
        // keep the domain wide; just avoid pathological overflow-free extremes
        amount = bound(amount, 1, type(uint128).max);

        // fund the contract directly so withdraw has something to send
        vm.deal(address(c), amount);

        // the owner is whoever deployed c (the test contract); exercise the
        // owner path with a fuzzed amount
        vm.deal(address(this), 0);
        vm.prank(c.Owner());
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // GENERAL RULE: whenever withdraw() succeeds, the entire contract
        // balance is transferred out to the OWNER, so c's own balance must be
        // zero and the owner must have received the funds. The mutant routes
        // the funds to msg.sender instead of Owner, breaking this rule for
        // inputs where the caller/recipient distinction matters.
        assertTrue(ok && address(c).balance == 0);
    }
}

