contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // keep the domain wide but admissible: a positive, fundable amount
        amount = bound(amount, 1 wei, 1 ether);

        // owner (deployer of C) is this test contract; give it funds and fund c via its receive()
        vm.deal(address(this), amount);
        (bool funded, ) = address(c).call{value: amount}("");
        assertTrue(funded);
        assertTrue(address(c).balance == amount);

        uint256 ownerBefore = address(this).balance;

        // owner withdraws the whole balance
