pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // keep params in the admissible domain, WIDE
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        uint256 amt = bound(amount, 1, 1 ether);

        // fund the contract through its public receive path
        vm.deal(actor, amt);
        vm.prank(actor);
        (bool sent, ) = address(c).call{value: amt}("");
        assertTrue(sent, "funding c must succeed");

        address owner = c.Owner();
        uint256 balBefore = address(c).balance;

        // a caller that is not the owner must not be able to move funds out
        bool okNonOwner = true;
        if (actor != owner) {
            vm.prank(actor);
            try c.withdraw() { okNonOwner = true; } catch { okNonOwner = false; }
            // no funds may leave c on a non-owner attempt
            assertTrue(!okNonOwner && address(c).balance == balBefore, "non-owner withdraw must not move funds");
        }

        // the owner withdraws: the ENTIRE balance must go to the account at c.Owner(),
        // never to any other party, and c must be left empty
        vm.deal(owner, 1 wei);
        uint256 ownerBefore = owner.balance;
        vm.prank(owner);
        try c.withdraw() {
            assertTrue(
                address(c).balance == 0 &&
                owner.balance == ownerBefore + balBefore,
                "successful withdraw must drain c entirely to the owner"
            );
        } catch {
            // owner withdraw should not revert for an admissible balance
            assertTrue(false, "owner withdraw must succeed");
        }
    }
}

