pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 tip) public {
        // keep amounts in an admissible, wide domain where funding and transfer succeed
        amount = bound(amount, 0, 1e24);
        tip = bound(tip, 0, 1e18);

        // owner is the deployer of c (this test contract)
        address owner = c.Owner();
        vm.assume(owner == address(this));

        // fund the contract with the fuzzed amount
        vm.deal(address(c), amount);
        // give the caller (owner) funds to attach the fuzzed tip, as withdraw is payable
        vm.deal(address(this), tip);
        uint256 ownerBefore = address(this).balance;
        uint256 contractBefore = address(c).balance;

        vm.prank(owner);
        bool ok;
        try c.withdraw{value: tip}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful withdraw by the owner must pay the ENTIRE
        // contract balance out of c, zeroing it, and credit exactly that drained
        // amount to the account at c.Owner(). The mutant pays msg.sender instead
        // of Owner, so whenever the caller is not the owner it breaks the
        // recipient convention and the credited amount/recipient is wrong.
        assertTrue(ok && address(c).balance == 0
            && address(this).balance - ownerBefore == contractBefore);
    }
}

